DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.checkout_receivable(uuid,uuid,jsonb,numeric,numeric,numeric,date,text,uuid,uuid,jsonb,text,uuid,integer)'::regprocedure) INTO definition; definition=replace(definition,'payment_source=''cash''','payment_source=''normal'''); definition=replace(definition,'payment_source<>''cash''','payment_source<>''normal'''); definition=replace(definition,'round((it->>''total'')::numeric/(it->>''qty'')::int/v_subtotal*p_total,2)','trunc((it->>''total'')::numeric/(it->>''qty'')::int/v_subtotal*p_total,2)'); definition=replace(definition,'round(v_gross/p_total*p_paid,2)','trunc(v_gross/p_total*p_paid,2)'); definition=replace(definition,'round(v_gross/p_total*p_credit,2)','trunc(v_gross/p_total*p_credit,2)'); definition=replace(definition,'FOR it IN SELECT * FROM jsonb_array_elements(p_items) LOOP','FOR it IN SELECT * FROM jsonb_array_elements(p_items) LOOP'); definition=replace(definition,'IF p_comanda IS NOT NULL THEN UPDATE public.comandas SET','UPDATE public.receivables SET service_id=(SELECT service_id FROM public.sales WHERE receivable_id=v_id LIMIT 1), professional_id=(SELECT professional_id FROM public.sales WHERE receivable_id=v_id LIMIT 1) WHERE id=v_id; IF p_comanda IS NOT NULL THEN UPDATE public.comandas SET'); EXECUTE definition; END $$;